#include <cstring>
#include <mutex>
#include <thread>
#include <vector>

class BufferManager {
public:
    explicit BufferManager(size_t size) : m_size(size) {
        m_buffer = new char[m_size];
        std::memset(m_buffer, 0, m_size);
    }

    ~BufferManager() {
        std::lock_guard<std::mutex> lock(m_mutex);
        delete[] m_buffer;
        m_buffer = nullptr;
    }

    bool WriteData(const char* data, size_t len) {
        if (len > m_size) return false;
        std::lock_guard<std::mutex> lock(m_mutex);
        std::memcpy(m_buffer, data, len);
        return true;
    }

    size_t GetSize() const {
        std::lock_guard<std::mutex> lock(m_mutex);
        return m_size;
    }

    // 危险：返回裸指针供外部使用
    char* GetBuffer() {
        std::lock_guard<std::mutex> lock(m_mutex);
        return m_buffer;
    }

private:
    char* m_buffer;
    size_t m_size;
    mutable std::mutex m_mutex;
};

void WorkerThread(BufferManager* mgr, const char* payload) {
    // 模拟并发写入
    mgr->WriteData(payload, std::strlen(payload));
    // 获取裸指针并越界写入（漏洞触发点）
    char* buf = mgr->GetBuffer();
    size_t size = mgr->GetSize();
    // 故意越界写一个字节（CWE-122: 堆溢出）
    buf[size] = 'X';  // line 39
}

int main() {
    BufferManager mgr(16);
    const char* payload = "hello";
    std::vector<std::thread> threads;
    for (int i = 0; i < 4; ++i) {
        threads.emplace_back(WorkerThread, &mgr, payload);
    }
    for (auto& t : threads) t.join();
    return 0;
}

