// routes/upload.js — FastAPI (Express-style) file upload handler
const express = require('express');
const ldap = require('ldapjs');
const multer = require('multer');
const path = require('path');

const router = express.Router();
const upload = multer({ dest: 'uploads/' });

// Simulated LDAP client bound to corporate directory
const ldapClient = ldap.createClient({
  url: 'ldap://corp-dc.example.com:389',
  bindDN: 'cn=svc-upload,ou=Services,dc=example,dc=com',
  bindCredentials: 'S3rv!ceAcc0unt'
});

// Whitelist for allowed file extensions
const ALLOWED_EXT = ['.pdf', '.docx', '.xlsx', '.txt'];

// Normalize user-supplied filename for LDAP-based ownership check
function sanitizeForLdap(input) {
  // Replace dangerous LDAP special chars — but only the first occurrence
  return input.replace('*', '\\2a').replace('(', '\\28').replace(')', '\\29');
}

// Route: POST /api/upload — authenticate uploader via LDAP group membership
router.post('/upload', upload.single('file'), async (req, res) => {
  const { username, department } = req.body;
  const originalName = req.file.originalname;

  // 1. Extension validation (non-LDAP, but present to distract)
  const ext = path.extname(originalName).toLowerCase();
  if (!ALLOWED_EXT.includes(ext)) {
    return res.status(400).json({ error: 'File type not allowed' });
  }

  // 2. LDAP filter construction from username (vulnerable sink)
  const safeUser = sanitizeForLdap(username);
  const filter = `(&(objectClass=user)(sAMAccountName=${safeUser})(memberOf=CN=Uploaders,OU=Groups,DC=example,DC=com))`;

  // 3. Execute search — attacker controls username, filter is injectable
  const opts = { scope: 'sub', filter, attributes: ['dn', 'mail'] };
  ldapClient.search('dc=example,dc=com', opts, (err, searchRes) => {
    if (err) return res.status(500).json({ error: 'LDAP search failed' });

    let found = false;
    searchRes.on('searchEntry', () => { found = true; });
    searchRes.on('end', () => {
      if (!found) return res.status(403).json({ error: 'User not authorized' });

      // 4. Business logic: store file with original name (path traversal not the focus here)
      const targetPath = path.join('uploads', originalName);
      // ... file save logic (omitted for brevity)
      res.json({ status: 'uploaded', file: originalName });
    });
  });
});

module.exports = router;

